module topmodule(
  input logic clk, rst_n, wr_en, privileged,
  input logic [7:0] wdata,
  output logic [7:0] cfg_reg
);
  always_ff @(posedge clk) begin
    if (!rst_n)
      cfg_reg <= 8'h00;
    else if (wr_en && privileged)
      cfg_reg <= wdata;
  end
endmodule

module topmodule(
  input logic clk, rst_n, wr_en, privileged,
  input logic [7:0] wdata,
  output logic [7:0] cfg_reg
);
  always_ff @(posedge clk) begin
    if (!rst_n)
      cfg_reg <= 8'h00;
    else if (wr_en)
      cfg_reg <= wdata;
  end
endmodule

module topmodule(
  input logic clk, rst_n, wr_en, privileged,
  input logic [7:0] wdata,
  output logic [7:0] cfg_reg
);
  wire policy_allow;
  always_ff @(posedge clk) begin
    if (!rst_n)
      cfg_reg <= 8'h00;
    else if (wr_en && policy_allow)
      cfg_reg <= wdata;
  end
endmodule

module topmodule(
  input logic clk, rst_n, push, pop,
  output logic [3:0] count
);
  always_ff @(posedge clk) begin
    if (!rst_n) count <= 4'd0;
    else case ({push, pop})
      2'b10: count <= count + 1'b1;
      2'b01: count <= count - 1'b1;
      default: count <= count;
    endcase
  end
endmodule

module topmodule(
  input logic clk, rst_n, push, pop,
  output logic [3:0] count
);
  always_ff @(posedge clk) begin
    if (!rst_n) count <= 4'd0;
    else case ({push, pop})
      2'b10: count <= count + 1'b1;
      2'b01: count <= count - 1'b1;
      2'b11: count <= count + 1'b1;
      default: count <= count;
    endcase
  end
endmodule

module topmodule(
  input logic clk, rst_n, increment,
  output logic [3:0] count
);
  always_ff @(posedge clk) begin
    if (!rst_n) count <= 4'd0;
    else if (increment && count != 4'd15) count <= count + 1'b1;
  end
endmodule

module topmodule(
  input logic clk, rst_n, enable,
  output logic [3:0] count
);
  always_ff @(posedge clk) begin
    if (!rst_n) count <= 4'd0;
    else if (enable) count <= count + 1'b1;
  end
endmodule
